from PIL import Image
import numpy as np
im=np.array(Image.open('/app/target.png').convert('RGB')); m=(im[:,:,0]<100)&(im[:,:,1]<100)&(im[:,:,2]<100)
H,W=m.shape; seen=np.zeros_like(m); comps=[]
for y,x in zip(*np.where(m)):
 if seen[y,x]: continue
 q=[(y,x)];seen[y,x]=1; a=0; ymin=ymax=y;xmin=xmax=x
 while q:
  yy,xx=q.pop();a+=1;ymin=min(ymin,yy);ymax=max(ymax,yy);xmin=min(xmin,xx);xmax=max(xmax,xx)
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    ny,nx=yy+dy,xx+dx
    if 0<=ny<H and 0<=nx<W and m[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;q.append((ny,nx))
 if a>5:comps.append((xmin,ymin,xmax-xmin+1,ymax-ymin+1,a))
print(sorted(comps))
PY

